def missing_parts(needed, available):
    have = set(available)
    return [p for p in needed if p not in have]

def longest_safe_stretch(rain, budget):
    best = 0
    total = 0
    left = 0
    for right in range(len(rain)):
        total += rain[right]
        while total > budget:
            total -= rain[left]
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    return best

def missing_badge(returns):
    n = len(returns)
    expected = n * (n + 1) // 2
    return expected - sum(returns)

def widest_tank(heights):
    left, right = 0, len(heights) - 1
    best = 0
    while left < right:
        width = right - left
        if heights[left] < heights[right]:
            volume = heights[left] * width
            left += 1
        else:
            volume = heights[right] * width
            right -= 1
        if volume > best:
            best = volume
    return best
